inputs.shell_command:
set -euo pipefail

echo '=== HEAD ==='
git rev-parse HEAD

echo '=== suspicious tracked paths ==='
paths="$(git ls-files | grep -Ei '(^|/)(p2p|direct-agent|local-agent-direct|host-discovery|device-discovery|webrtc)([-_./]|$)' || true)"
if [ -n "$paths" ]; then printf '%s\n' "$paths"; echo 'TRACKED_PATH_SCAN=dirty' >&2; exit 51; fi
echo 'TRACKED_PATH_SCAN=clean'

echo '=== suspicious tracked text ==='
pattern='p2p-link|direct[ -]?p2p|direct[ -]?agent|local-agent:direct|local-agent-direct|host[ -]?discovery|device[ -]?discovery|ASOL_DEVICE_DISCOVERY|GOVA_DIRECT_|48732|x25519|webrtc|werift|direct-auth-results|direct-auth/'
hits="$(git grep -I -n -i -E "$pattern" -- . ':!package-lock.json' || true)"
if [ -n "$hits" ]; then printf '%s\n' "$hits"; echo 'TRACKED_TEXT_SCAN=dirty' >&2; exit 52; fi
echo 'TRACKED_TEXT_SCAN=clean'

echo '=== lockfile/dependency scan ==='
if grep -Ein '"werift"|node_modules/werift|node_modules/@werift|x25519|direct-p2p|local-agent-direct' package-lock.json; then echo 'LOCKFILE_SCAN=dirty' >&2; exit 53; fi
echo 'LOCKFILE_SCAN=clean'

echo '=== package contract scan ==='
node - <<'NODE'
const fs = require('fs');
const root = JSON.parse(fs.readFileSync('package.json','utf8'));
const local = JSON.parse(fs.readFileSync('packages/local-agent-core/package.json','utf8'));
const rootText = JSON.stringify(root).toLowerCase();
const localText = JSON.stringify(local).toLowerCase();
const banned = ['local-agent:direct','local-agent-direct','device:discover','werift','./direct'];
for (const token of banned) {
  if (rootText.includes(token) || localText.includes(token)) {
    console.error('PACKAGE_CONTRACT_SCAN=dirty token=' + token);
    process.exit(54);
  }
}
console.log('PACKAGE_CONTRACT_SCAN=clean');
NODE

echo '=== retained Local Runner checks ==='
test -f .github/workflows/local-agent-gateway.yml
test -f .github/workflows/local-agent-main.yml
test -f scripts/local-agent-gateway.ts
test -f scripts/local-agent-main-apply.ts
test -f packages/local-agent-core/src/request-contract.ts
npm run test:local-agent-core
npm run test:local-agent-workflows

echo 'P2P_CODE_REMOVAL_VERIFICATION=clean'
